// Package contract 提供 Contract Testing 內建驗證功能
// 根據 schema-first 路由的 metadata 自動驗證 handler 的行為
// 確保 AI 生成的程式碼符合宣告的合約
//
// @ai:generated by=claude-opus-4-6 date=2026-02-27
package contract

// @ai purpose: Contract Testing 核心 — Test / TestAll / TestRoute 三個公開測試函式
// @ai input: *testing.T、*router.Router、TestCase / RunConfig
// @ai output: 無（透過 t.Errorf / t.Skip 回報結果）
// @ai sideeffect: 呼叫 router.ServeHTTP（httptest 模式，不開真實 port）
// date: 2026-05-23

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"maps"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/maoxiaoyue/hypgo/pkg/eval"
	"github.com/maoxiaoyue/hypgo/pkg/router"
	"github.com/maoxiaoyue/hypgo/pkg/schema"
)

// TestCase 定義單一 contract 測試案例
type TestCase struct {
	// Name 案例名稱（選填），RecordHistory 時寫進歷史。同一條路由有多個案例（成功、錯誤路徑…）時，
	// hyp eval-report 以它分開統計；沒有名稱時以輸入的 hash 區分
	Name string

	// Route 格式為 "METHOD /path"，例如 "POST /api/users"
	Route string

	// Input 為 JSON 格式的請求 body
	Input string

	// Headers 為自訂請求標頭
	Headers map[string]string

	// Query 為 URL query 參數
	Query map[string]string

	// ExpectStatus 為期望的 HTTP 狀態碼
	ExpectStatus int

	// ExpectSchema 為 true 時，驗證回應 body 是否符合 Output schema
	ExpectSchema bool

	// StrictFields 與 ExpectSchema 併用：回應裡出現 schema 沒有宣告的欄位也算不符
	// （例如把 password_hash 一起回出去）。預設不檢查，多回的欄位不算違約
	StrictFields bool

	// ExpectBody 為非空時，精確比對回應 body
	ExpectBody string

	// Graders 為 probabilistic 評判器清單（LLM-as-judge、embedding 相似度等，
	// 見 pkg/eval）。在所有 deterministic 檢查（狀態碼 / schema / body）通過後
	// 依序執行；任一評判器本身出錯（如 LLM 連線失敗）視為測試失敗
	Graders []eval.Grader

	// PassThreshold 為評分門檻：Graders 的加權平均分數（等權）低於此值時
	// 測試失敗。0 表示不設門檻——只記錄分數（t.Logf / eval history），不影響
	// pass/fail，方便漸進導入
	PassThreshold float64

	// RecordHistory 為 true 時，Test 把結果（含 Graders 的分數）append 到 .hyp/eval_history.jsonl，
	// 供 hyp eval-report 看趨勢。TestAll 請用 RunConfig.RecordHistory
	RecordHistory bool

	// schemaRoute 為內部欄位：TestAll / Observe 已持有路由宣告，直接帶入，
	// 不必再以路徑查 registry（手動 Test 為 nil，改以實際路徑比對路由樣式）
	schemaRoute *schema.Route

	// generated 表示這個案例是 TestAll / Observe 依 schema 自動產生的：
	// 輸入不合規則時問題在產生器而不是使用者，錯誤訊息要這樣說
	generated bool
}

// Test 執行單一 contract 測試
//
// @ai purpose: 手動執行單一路由的 contract 驗證，適合邊界條件與錯誤路徑測試
// @ai input: *testing.T、*router.Router、TestCase（完整定義）
// @ai output: 無
// @ai sideeffect: 呼叫 t.Errorf / t.Fatalf
// date: 2026-05-23
func Test(t *testing.T, r *router.Router, tc TestCase) {
	t.Helper()
	testInternal(t, r, tc)
}

// runTestOnce 執行一次 contract 測試並回傳結果，不接觸 *testing.T
// 這是純執行函式，讓重試迴圈可以多次呼叫而不污染 t 的狀態
//
// @ai purpose: 將 HTTP 執行邏輯與 t.Errorf 解耦，支援 TestAll 的重試機制
// @ai input: *router.Router（被測路由器）、TestCase（測試定義）
// @ai output: pass bool、reason string（失敗原因）、scores（Graders 的評分，無 Graders 時為 nil）
// @ai sideeffect: 無（不呼叫任何 t.* 方法；Graders 可能發出 LLM HTTP 請求）
// date: 2026-05-23
func runTestOnce(r *router.Router, tc TestCase) (pass bool, reason string, scores map[string]float64) {
	pass, reason, scores, _ = runTestTimed(r, tc)
	return pass, reason, scores
}

// runTestTimed 同 runTestOnce，另外回傳 Graders 花的時間（歷史紀錄把它與 handler 的時間分開）
func runTestTimed(r *router.Router, tc TestCase) (pass bool, reason string, scores map[string]float64, graderTime time.Duration) {
	method, path := parseRoute(tc.Route)
	if method == "" || path == "" {
		return false, fmt.Sprintf("invalid route format: %q (expected \"METHOD /path\")", tc.Route), nil, 0
	}

	// 什麼都沒要求的案例一律通過（連 404 都是綠的），多半是忘了填
	if !tc.generated && tc.ExpectStatus == 0 && !tc.ExpectSchema && tc.ExpectBody == "" && len(tc.Graders) == 0 {
		return false, fmt.Sprintf("[%s] nothing to check: set ExpectStatus, ExpectSchema, ExpectBody or Graders", tc.Route), nil, 0
	}

	req := tc.request(method, path)
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)

	// 取得路由宣告：TestAll 已帶入；手動 Test 要驗 schema 時以路徑查。都沒有就用零值，只檢查狀態碼
	var route schema.Route
	if tc.schemaRoute != nil {
		route = *tc.schemaRoute
	} else if tc.ExpectSchema {
		s, ok := lookupSchema(method, req.URL.Path)
		if !ok {
			return false, fmt.Sprintf("[%s] no schema registered for validation", tc.Route), nil, 0
		}
		route = *s
	}
	if _, ok, why := validateExchange(route, tc, w.Code, w.Header().Get("Content-Type"), w.Body.Bytes()); !ok {
		return false, fmt.Sprintf("[%s] %s", tc.Route, why), nil, 0
	}

	// 精確比對 body
	if tc.ExpectBody != "" {
		got := strings.TrimSpace(w.Body.String())
		want := strings.TrimSpace(tc.ExpectBody)
		if got != want {
			return false, fmt.Sprintf("[%s] body = %q, want %q", tc.Route, got, want), nil, 0
		}
	}

	// Probabilistic 評分：deterministic 檢查全數通過後才執行
	//（結構都不對的回應沒有評分意義）
	if len(tc.Graders) > 0 {
		start := time.Now()
		pass, reason, scores = runGraders(tc, w.Body.String())
		return pass, reason, scores, time.Since(start)
	}

	return true, "", nil, 0
}

// request 依 TestCase 組出請求；有 Input 時預設 Content-Type: application/json（Headers 可覆寫）
func (tc TestCase) request(method, path string) *http.Request {
	req := buildRequest(method, path, tc.Input, tc.Headers, tc.Query)
	if tc.Input != "" && req.Header.Get("Content-Type") == "" {
		req.Header.Set("Content-Type", "application/json")
	}
	return req
}

// validateExchange 依序檢查一次 HTTP 交換：Input schema → 狀態碼 → 回應 body 非空 → Content-Type → 回應 schema。
// runTestOnce（Test / TestAll）與 Observe 共用，兩邊判定才不會分歧；reason 為第一個失敗步驟的原因。
// route 沒有 Input / Output 時只檢查狀態碼；tc.ExpectStatus 為 0 時不檢查狀態碼
func validateExchange(route schema.Route, tc TestCase, code int, contentType string, body []byte) (steps []ValidationStep, pass bool, reason string) {
	pass = true
	step := func(name, okDetail string, err error) {
		s := ValidationStep{Name: name, Pass: err == nil, Detail: okDetail}
		if err != nil {
			s.Detail = err.Error()
			if pass {
				pass, reason = false, s.Detail
			}
		}
		steps = append(steps, s)
	}

	// 送出的 Input 要符合宣告——但只在期望成功時：測錯誤路徑就是要送不合格的輸入
	// （先前期望 422 並開 ExpectSchema 時，測試被自己的 Input 檢查判失敗，宣告的錯誤型別永遠驗不到）。
	// 排在最前面：輸入不合格時，後面的狀態碼不符只是結果
	expectOK := tc.ExpectStatus == 0 || (tc.ExpectStatus >= 200 && tc.ExpectStatus < 300)
	if route.Input != nil && tc.Input != "" && expectOK {
		var err error
		if e := validateRequest([]byte(tc.Input), route.Input); e != nil {
			err = fmt.Errorf("request schema validation failed: %w", e)
			if tc.generated {
				err = fmt.Errorf("the auto-generated input does not satisfy %s (%w); teach the generator with "+
					"contract.RegisterSampleValue(tag, value), or skip this route (RunConfig.Skip) and cover it with contract.Test", route.InputName, e)
			}
		}
		step(fmt.Sprintf("Input Schema (%s)", route.InputName), "matches schema", err)
	}

	if tc.ExpectStatus > 0 {
		var err error
		if code != tc.ExpectStatus {
			err = fmt.Errorf("status = %d, want %d", code, tc.ExpectStatus)
		}
		step("Status Code", fmt.Sprintf("got %d, want %d", code, tc.ExpectStatus), err)
	}

	// 回應 body 的 schema：該狀態碼在 Responses 宣告了 Type 就用它，否則 2xx 用 Output；
	// 非 2xx 且未宣告時不驗 body——錯誤回應不是 Output 的形狀（先前一律拿 Output 驗，
	// 手動 Test 期望 404 並開 ExpectSchema 時必定失敗）
	bodyType, bodyName := route.Output, route.OutputName
	if rs, ok := route.Responses[code]; ok && rs.Type != nil {
		bodyType, bodyName = rs.Type, rs.TypeName
	} else if code < 200 || code >= 300 {
		bodyType = nil
	}

	hasBody := len(bytes.TrimSpace(body)) > 0
	if bodyType != nil {
		var err error
		if !hasBody {
			err = errors.New("response body is empty")
		}
		step("Response Body", "body present", err)
	}

	if bodyType != nil && hasBody {
		// 宣告了 JSON 型別的回應要以 JSON 送出：先前 text/html 的 JSON 也通過，瀏覽器與多數客戶端不會當 JSON 解
		var err error
		if mt, _, _ := strings.Cut(contentType, ";"); !isJSONType(strings.ToLower(strings.TrimSpace(mt))) {
			err = fmt.Errorf("response Content-Type is %q, want application/json", contentType)
		}
		step("Content-Type", "application/json", err)
	}

	if bodyType != nil && hasBody {
		var err error
		if e := validateResponse(body, bodyType, tc.StrictFields); e != nil {
			err = fmt.Errorf("response schema validation failed: %w", e)
		}
		step(fmt.Sprintf("Output Schema (%s)", bodyName), "matches schema", err)
	}
	return steps, pass, reason
}

// isJSONType 回報媒體類型是否為 JSON（application/json 或 +json 結尾，如 application/problem+json）
func isJSONType(mediaType string) bool {
	return mediaType == "application/json" || strings.HasSuffix(mediaType, "+json")
}

// runGraders 依序執行 TestCase 的評判器並聚合分數（等權平均）。
// 任一評判器出錯（如 LLM 連線失敗）視為測試失敗——使用者主動掛上
// 評判器即表示評分是合約的一部分，靜默跳過會給出假信心。
// PassThreshold=0 時只記錄分數不設門檻
func runGraders(tc TestCase, output string) (pass bool, reason string, scores map[string]float64) {
	sample := eval.Sample{Route: tc.Route, Input: tc.Input, Output: output}
	results := make([]eval.GraderResult, 0, len(tc.Graders))
	scores = make(map[string]float64, len(tc.Graders)+1)
	// 同名的評判器加序號（llm_judge#2）：兩個 Rubric 不同的 LLMJudge 先前互相覆蓋，
	// aggregate 算了兩個分數，紀錄卻只剩一個。contract / aggregate 是保留名稱
	seen := map[string]int{"contract": 1, "aggregate": 1}

	for _, g := range tc.Graders {
		res, err := g.Grade(context.Background(), sample)
		if err != nil {
			return false, fmt.Sprintf("[%s] grader %q failed: %v", tc.Route, g.Name(), err), scores
		}
		// 這個條件也擋 NaN：先前 NaN 讓 agg < threshold 為 false 而通過門檻，紀錄也寫不進去
		if !(res.Score >= 0 && res.Score <= 1) {
			return false, fmt.Sprintf("[%s] grader %q returned invalid score %v (must be 0.0-1.0)", tc.Route, g.Name(), res.Score), scores
		}
		if res.Name == "" {
			res.Name = g.Name()
		}
		seen[res.Name]++
		if n := seen[res.Name]; n > 1 {
			res.Name = fmt.Sprintf("%s#%d", res.Name, n)
		}
		results = append(results, res)
		scores[res.Name] = res.Score
	}

	agg := eval.Aggregate(results)
	scores["aggregate"] = agg

	if tc.PassThreshold > 0 && agg < tc.PassThreshold {
		var detail strings.Builder
		for _, r := range results {
			fmt.Fprintf(&detail, "\n  %s = %.2f", r.Name, r.Score)
			if r.Reason != "" {
				fmt.Fprintf(&detail, " (%s)", r.Reason)
			}
		}
		return false, fmt.Sprintf("[%s] eval score %.2f below threshold %.2f:%s",
			tc.Route, agg, tc.PassThreshold, detail.String()), scores
	}

	return true, "", scores
}

// testInternal 為 Test() 的內部共用實作
// 呼叫 runTestOnce 並將失敗結果報告至 t.Errorf
//
// @ai purpose: 橋接純執行函式（runTestOnce）與 testing.T 回報機制
// @ai input: *testing.T、*router.Router、TestCase
// @ai output: 無
// @ai sideeffect: 呼叫 t.Errorf / t.Fatalf
// date: 2026-05-23
func testInternal(t *testing.T, r *router.Router, tc TestCase) {
	t.Helper()
	start := time.Now()
	pass, reason, scores, graderTime := runTestTimed(r, tc)
	if len(scores) > 0 {
		t.Logf("eval scores %s: %v", tc.Route, scores)
	}
	if !pass {
		t.Errorf("contract: %s", reason)
	}
	if tc.RecordHistory {
		recordHistory(t, tc, tc.Route, pass, reason, scores, time.Since(start)-graderTime, graderTime, 1)
	}
}

// gitCommit 只查一次：同一個測試行程裡 commit 不會變，每筆紀錄都開子行程太慢
var gitCommit = sync.OnceValue(eval.GitShortCommit)

// recordHistory 寫入一筆 eval history。寫入失敗讓測試失敗：要求記錄卻默默沒記，
// 使用者要到看趨勢時才發現資料是斷的（通過的測試不顯示 t.Logf，所以不用 Logf）
func recordHistory(t *testing.T, tc TestCase, route string, pass bool, reason string, graderScores map[string]float64, latency, graderTime time.Duration, attempts int) {
	t.Helper()
	status, score := "fail", 0.0
	if pass {
		status, score = "pass", 1.0
	}
	// contract 分數 + 各 Grader 的評分（llm_judge/similarity/aggregate…）
	scores := map[string]float64{"contract": score}
	maps.Copy(scores, graderScores)
	err := eval.AppendHistory(eval.EvalRecord{
		Timestamp:  time.Now().UTC(),
		GitCommit:  gitCommit(),
		Route:      route,
		Case:       tc.Name,
		Status:     status,
		Scores:     scores,
		Attempts:   attempts,
		LatencyMs:  latency.Milliseconds(),
		GraderMs:   graderTime.Milliseconds(),
		InputHash:  eval.HashInput(tc.Input),
		FailReason: reason,
	})
	if err != nil {
		t.Errorf("contract: record history: %v", err)
	}
}

// TestAll 自動測試所有 schema-registered 路由
// REST 路由：發送 HTTP 請求並驗證 Input/Output
// 非 REST 路由：驗證 schema 定義完整性（不發送請求）
//
// 可選傳入 RunConfig 啟用並行、重試、速率限制、FailFast 與 History 記錄：
//
//	contract.TestAll(t, r)                              // 向後相容，循序執行
//	contract.TestAll(t, r, contract.RunConfig{
//	    Parallel: true, MaxWorkers: 4, RetryCount: 2,
//	    RecordHistory: true,                            // append 到 .hyp/eval_history.jsonl
//	})
//
// @ai purpose: 一鍵驗證所有 schema-registered 路由的 contract，支援執行引擎設定與歷史記錄
// @ai input: *testing.T、*router.Router、可選的 RunConfig（向後相容）
// @ai output: 無
// @ai sideeffect: 呼叫 t.Run / t.Parallel / t.Errorf / t.Logf / t.Skip；RecordHistory=true 時 append .hyp/eval_history.jsonl
// date: 2026-05-23
func TestAll(t *testing.T, r *router.Router, cfgs ...RunConfig) {
	t.Helper()

	cfg := mergeRunConfig(cfgs)

	routes := routesOf(r)
	if len(routes) == 0 {
		t.Skip("no schema-registered routes found")
	}

	// FailFast 信號：atomic 確保 goroutine 間無鎖可見
	var aborted atomic.Bool

	// 並行上限：t.Parallel 的並行數由 go test -parallel 決定，這裡再以 MaxWorkers 收斂
	sem := make(chan struct{}, cfg.MaxWorkers)

	// 速率限制器：由所有子測試 goroutine 共享競爭接收（goroutine-safe）
	var limiterCh <-chan time.Time
	if cfg.RateLimit > 0 {
		ticker := time.NewTicker(time.Second / time.Duration(cfg.RateLimit))
		limiterCh = ticker.C
		// t.Cleanup 確保 ticker 在所有並行子測試完成後才停止
		t.Cleanup(ticker.Stop)
	}

	for _, route := range routes {
		if route.IsREST() {
			name := route.Method + " " + route.Path
			t.Run(name, func(t *testing.T) {
				// FailFast 檢查：並行模式下在 t.Parallel() 後仍需檢查
				if aborted.Load() {
					t.Skip("skipped: FailFast abort")
					return
				}
				if cfg.skips(route) {
					t.Skip("skipped: RunConfig.Skip")
					return
				}

				if cfg.Parallel {
					t.Parallel()
					sem <- struct{}{}
					defer func() { <-sem }()
				}

				// 並行模式下，goroutine 重新啟動後再次檢查
				if aborted.Load() {
					t.Skip("skipped: FailFast abort")
					return
				}

				// 速率限制：所有 goroutine 競爭接收同一個 ticker channel
				if cfg.RateLimit > 0 {
					<-limiterCh
				}

				tc := cfg.testCase(route)

				// 重試迴圈（含計時，用於 RecordHistory）
				start := time.Now()
				var pass bool
				var reason string
				var graderScores map[string]float64
				var graderTime time.Duration
				attempts := 0
				for attempts <= cfg.RetryCount {
					if attempts > 0 {
						t.Logf("[retry %d/%d] %s %s", attempts, cfg.RetryCount,
							route.Method, route.Path)
						if cfg.RetryDelay > 0 {
							time.Sleep(cfg.RetryDelay)
						}
					}
					var g time.Duration
					pass, reason, graderScores, g = runTestTimed(r, tc)
					graderTime += g
					attempts++
					if pass {
						break
					}
				}
				latency := time.Since(start)

				if !pass {
					t.Errorf("contract: %s", reason)
					if cfg.FailFast {
						aborted.Store(true)
					}
				}

				// 歷史記錄：RecordHistory=true 時 append 結果
				if cfg.RecordHistory {
					recordHistory(t, tc, route.Method+" "+route.Path, pass, reason, graderScores, latency-graderTime, graderTime, attempts)
				}
			})
		} else {
			// 非 REST 路由：驗證 schema 定義完整性
			name := route.Protocol + "|" + route.Command
			t.Run(name, func(t *testing.T) {
				if aborted.Load() {
					t.Skip("skipped: FailFast abort")
					return
				}
				if cfg.Parallel {
					t.Parallel()
					sem <- struct{}{}
					defer func() { <-sem }()
				}
				start := time.Now()
				testSchemaCompleteness(t, route)
				// FailFast：testSchemaCompleteness 失敗後設定 aborted
				if t.Failed() && cfg.FailFast {
					aborted.Store(true)
				}
				if cfg.RecordHistory {
					reason := ""
					if t.Failed() {
						reason = "schema incomplete"
					}
					recordHistory(t, TestCase{}, name, !t.Failed(), reason, nil, time.Since(start), 0, 1)
				}
			})
		}
	}
}

// testSchemaCompleteness 驗證非 REST 路由的 schema 定義完整性
// 不發送實際請求，只檢查 schema 本身的品質
//
// @ai purpose: 對 gRPC / Bot / MCP / WebSocket / CLI 路由做 schema 品質檢查
// @ai input: *testing.T、schema.Route（非 REST 路由）
// @ai output: 無
// @ai sideeffect: 呼叫 t.Errorf
// date: 2026-05-23
func testSchemaCompleteness(t *testing.T, route schema.Route) {
	t.Helper()

	label := route.Protocol + "|" + route.Command

	if route.Command == "" {
		t.Errorf("[%s] missing Command", label)
	}
	if route.Summary == "" {
		t.Errorf("[%s] missing Summary", label)
	}
	// Input/Output 不強制要求（有些命令確實沒有 Input 或 Output）
	// 但如果有，型別名稱應該已自動填入
	if route.Input != nil && route.InputName == "" {
		t.Errorf("[%s] has Input but missing InputName", label)
	}
	if route.Output != nil && route.OutputName == "" {
		t.Errorf("[%s] has Output but missing OutputName", label)
	}
}

// TestRoute 測試單一路由是否已註冊且可回應
//
// @ai purpose: 簡易路由存在性驗證，不需要 schema 宣告
// @ai input: *testing.T、*router.Router、method string、path string、expectStatus int
// @ai output: 無
// @ai sideeffect: 呼叫 t.Errorf
// date: 2026-05-23
func TestRoute(t *testing.T, r *router.Router, method, path string, expectStatus int) {
	t.Helper()

	req := httptest.NewRequest(strings.ToUpper(strings.TrimSpace(method)), path, nil)
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)

	if w.Code != expectStatus {
		t.Errorf("%s %s: status = %d, want %d", method, path, w.Code, expectStatus)
	}
}

// routesOf 回傳要測的路由：REST 只取 r 上有註冊的，其餘協議取全域 registry 的全部。
// 先前 REST 也取全域 registry：同一個測試行程裡別的 router 註冊的路由（admin 與 public 兩個 router、
// 其他測試建的 router）會被拿來打 r，全部 404
func routesOf(r *router.Router) []schema.Route {
	registered := make(map[string]bool)
	for _, ri := range r.Routes() {
		registered[ri.Method+" "+ri.Path] = true
	}
	var out []schema.Route
	for _, route := range schema.Global().All() {
		if !route.IsREST() || registered[route.Method+" "+route.Path] {
			out = append(out, route)
		}
	}
	return out
}

// lookupSchema 依實際請求路徑找 REST schema：先精確查表（靜態路由），再比對 :param / *wildcard 樣式。
// 先前只精確查表，手動 Test 傳 "GET /api/users/1" 永遠找不到 "/api/users/:id" 的 schema
func lookupSchema(method, path string) (*schema.Route, bool) {
	if s, ok := schema.Global().Get(method, path); ok {
		return s, true
	}
	for _, rt := range schema.Global().All() {
		if rt.IsREST() && rt.Method == method && pathMatches(rt.Path, path) {
			return &rt, true
		}
	}
	return nil, false
}

// pathMatches 回報 path 是否符合路由樣式（:name 吃一個非空區段，*name 吃剩餘全部）
func pathMatches(pattern, path string) bool {
	ps, xs := strings.Split(pattern, "/"), strings.Split(path, "/")
	for i, p := range ps {
		if strings.HasPrefix(p, "*") {
			return true
		}
		if i >= len(xs) {
			return false
		}
		if strings.HasPrefix(p, ":") {
			if xs[i] == "" {
				return false
			}
		} else if p != xs[i] {
			return false
		}
	}
	return len(ps) == len(xs)
}

// parseRoute 解析 "METHOD /path" 格式
//
// @ai purpose: 內部工具函式，將 TestCase.Route 字串拆分為 method 和 path
// @ai input: route string（格式 "METHOD /path"）
// @ai output: method string、path string（格式不正確時均為空字串）
// @ai sideeffect: 無
// date: 2026-05-23
func parseRoute(route string) (method, path string) {
	parts := strings.SplitN(route, " ", 2)
	if len(parts) != 2 {
		return "", ""
	}
	// 方法轉大寫，與 schema / router 的註冊一致（先前 "get /ok" 送出小寫方法而 405）
	return strings.ToUpper(strings.TrimSpace(parts[0])), strings.TrimSpace(parts[1])
}
